// Payload de los Database Webhooks de Supabase: { type, table, schema, record, old_record }.
// Solo sigue si cambió el estado: reclasificar el tipo u otros UPDATE no avisan al estudiante.
const { type, table, record, old_record: anterior } = $input.first().json.body ?? {};
if (type !== 'UPDATE' || table !== 'solicitudes' || !record?.id || !record?.estudiante_id || !anterior) {
  return [];
}
if (record.estado === anterior.estado) {
  return [];
}
return [{ json: { ...record, estado_anterior: anterior.estado } }];

const solicitud = $('Leer cambio').first().json;
const estudiante = $('Buscar estudiante').first().json;
const app = $env.APP_URL.replace(/\/$/, '');

// Espejo de ETIQUETA_ESTADO (web/src/lib/dominio.ts).
const ESTADOS = {
  pendiente: 'Pendiente',
  en_proceso: 'En proceso',
  finalizada: 'Finalizada',
  rechazada: 'Rechazada',
};
const MENSAJES = {
  en_proceso: 'La coordinación empezó a revisar tu solicitud.',
  finalizada: 'Tu solicitud fue resuelta y el caso quedó cerrado.',
  rechazada: 'Tu solicitud fue rechazada. Abajo está el motivo.',
};

// La observación la escribe el admin y el asunto el estudiante: nunca van al HTML sin escapar.
const esc = (texto) => String(texto ?? '').replace(/[&<>"']/g, (c) =>
  ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);

const estado = ESTADOS[solicitud.estado] ?? solicitud.estado;
const anterior = ESTADOS[solicitud.estado_anterior] ?? solicitud.estado_anterior;
// El trigger validar_cambio_solicitud() deja en observaciones solo la nota de esta transición.
const observacion = solicitud.observaciones
  ? `<p><strong>Observación de la coordinación:</strong></p>
<blockquote>${esc(solicitud.observaciones).replace(/\n/g, '<br>')}</blockquote>`
  : '';

return [{
  json: {
    solicitud_id: solicitud.id,
    tipo_aviso: 'cambio_estado',
    destinatario: estudiante.correo,
    asunto: `Tu solicitud está ${estado.toLowerCase()}: ${solicitud.asunto} - Gestión de Solicitudes`,
    cuerpo: `<h2>Tu solicitud cambió de estado</h2>
<p>Hola ${esc(estudiante.nombre)},</p>
<p>${MENSAJES[solicitud.estado] ?? ''}</p>
<ul>
  <li><strong>Asunto:</strong> ${esc(solicitud.asunto)}</li>
  <li><strong>Estado:</strong> ${esc(anterior)} → <strong>${esc(estado)}</strong></li>
</ul>
${observacion}
<p><a href="${app}/mis-solicitudes/${solicitud.id}">Ver mi solicitud</a></p>`,
  },
}];
